fn has_close_elements(numbers: [f64], threshold: f64) -> bool:
    """Check if in given list of numbers, are any two numbers closer to each other than
    given threshold.
    >>> has_close_elements([1.0, 2.0, 3.0], 0.5)
    False
    >>> has_close_elements([1.0, 2.8, 3.0, 4.0, 5.0, 2.0], 0.3)
    True"""
    for (idx, elem) in enumerate(numbers):
        for (idx2, elem2) in enumerate(numbers):
            if idx != idx2:
                distance = abs(elem - elem2)
                if distance < threshold:
                    return True
    return False

fn is_palindrome(n: int) -> bool:
    s = str(n)
    size = len(s)
    for i in range(size // 2):
        if s[i] != s[size - 1 - i]:
            return False
    return True

fn even_odd_palindrome(n: int) -> (int, int):
    """Count the even and odd integer palindromes in the range 1..n, inclusive."""
    var even_palindrome_count = 0
    var odd_palindrome_count = 0

    for i in range(1, n + 1):
        if i % 2 == 1 and is_palindrome(i):
            odd_palindrome_count += 1
        elif i % 2 == 0 and is_palindrome(i):
            even_palindrome_count += 1
    return (even_palindrome_count, odd_palindrome_count)

test "even_odd_palindrome":
    assert even_odd_palindrome(3) == (1, 2)
    assert even_odd_palindrome(12) == (4, 6)

