        return False
    month = month_s.to_int() ?? 0
    day = day_s.to_int() ?? 0
    if month_s.to_int() is None or day_s.to_int() is None:
        return False
    if month < 1 or month > 12:
        return False
    if month in [1, 3, 5, 7, 8, 10, 12] and (day < 1 or day > 31):
        return False
    if month in [4, 6, 9, 11] and (day < 1 or day > 30):
        return False
    if month == 2 and (day < 1 or day > 29):
        return False
    return True

