fn intersection(interval1: (int, int), interval2: (int, int)) -> str:
    """Return "YES" if the length of the intersection of the two closed intervals is prime, otherwise "NO"."""
    s1, e1 = interval1
    s2, e2 = interval2
    l = max(s1, s2)
    r = min(e1, e2)
    length = r - l
    if length > 0 and is_prime(length):
        return "YES"
    return "NO"

