fn fix_spaces(text: str) -> str:
    """Replace spaces with underscores, and runs of more than 2 spaces with a single dash."""
    var new_text = ""
    var i = 0
    var start = 0
    var end = 0
    while i < len(text):
        if text[i] == " ":
            end += 1
        else:
            if end - start > 2:
                new_text += "-" + text[i]
            elif end - start > 0:
                for k in range(end - start):
                    new_text += "_"
                new_text += text[i]
            else:
                new_text += text[i]
            start = i + 1
            end = i + 1
        i += 1
    if end - start > 2:
        new_text += "-"
    elif end - start > 0:
        for k in range(end - start):
            new_text += "_"
    return new_text

test "fix_spaces":
