    (1, 1)
    >>> even_odd_count(123) 
    (1, 2)"""
    var even_count = 0
    var odd_count = 0
    for i in str(abs(num)):
        digit = ord(i) - ord("0")
        if digit % 2 == 0:
            even_count += 1
        else:
