fn solve(var s: str) -> str:
    'You are given a string s.\n    if s[i] is a letter, reverse its case from lower to upper or vise versa, \n    otherwise keep it as it is.\n    If the string contains no letters, reverse the string.\n    The function should return the resulted string.\n    Examples\n    >>> solve("1234") \n    "4321"\n    >>> solve("ab") \n    "AB"\n    >>> solve("#a@C") \n    "#A@c"'
    var flg = 0
    var idx = 0
    var new_str = list(s)
    for i in s:
        if i.isalpha():
            new_str[idx] = i.swapcase()
            flg = 1
        idx += 1
    s = ''
    for i in new_str:
        s += i
    if flg == 0:
        return s[len(s)::-1]
    return s

