    Return the string with numbers sorted from smallest to largest
    >>> sort_numbers('three one five')
    'one three five'"""
    value_map = {'zero': 0, 'one': 1, 'two': 2, 'three': 3, 'four': 4, 'five': 5, 'six': 6, 'seven': 7, 'eight': 8, 'nine': 9}
