fn is_multiply_prime(a: int) -> bool:
    """Return true if the given number is the multiplication of 3 prime numbers, false otherwise.
    Knowing that a is less than 100.
    Example: is_multiply_prime(30) is true, since 30 = 2 * 3 * 5.
    """
    if a <= 1:
        return False
    var isprime = [True for k in range(a + 1)]
    for i in range(2, a + 1):
        if isprime[i]:
            for j in range(i + i, a + 1, i):
                isprime[j] = False
    var cnt = 0
    var tmp = a
    for i in range(2, a + 1):
        while isprime[i] and tmp % i == 0:
            tmp //= i
            cnt += 1
    return cnt == 3

