fn k_smallest_pairs(nums1: [int], nums2: [int], k: int) -> [[int]]:
    var queue: Heap[(int, int, int)] = Heap([])
    if len(nums1) > 0 and len(nums2) > 0:
        queue.push((nums1[0] + nums2[0], 0, 0))
    var pairs: [[int]] = []
    while len(queue) > 0 and len(pairs) < k:
        top = queue.pop_min()
        if top is not None:
            _, i, j = top
            pairs.append([nums1[i], nums2[j]])
            if i < len(nums1) and j + 1 < len(nums2):
                queue.push((nums1[i] + nums2[j + 1], i, j + 1))
            if j == 0:
                if i + 1 < len(nums1) and len(nums2) > 0:
                    queue.push((nums1[i + 1] + nums2[0], i + 1, 0))
    return pairs

