fn sumofFactors(var n: int) -> int:
    if n % 2 != 0:
        return 0
    var res = 1
    for i in range(2, int(math.sqrt(n)) + 1):
        var count = 0
        var curr_sum = 1
        var curr_term = 1
        while n % i == 0:
            count = count + 1
            n = n // i
            if i == 2 and count == 1:
                curr_sum = 0
            curr_term = curr_term * i
            curr_sum = curr_sum + curr_term
        res = res * curr_sum
    if n >= 2:
        res = res * (1 + n)
    return res

