fn max_subarray_product(arr: [int]) -> int:
    n = len(arr)
    var max_ending_here = 1
    var min_ending_here = 1
    var max_so_far = 0
    var flag = 0
    for i in range(0, n):
        if arr[i] > 0:
            max_ending_here = max_ending_here * arr[i]
            min_ending_here = min(min_ending_here * arr[i], 1)
            flag = 1
