fn get_Char(strr: str) -> str:
    var summ = 0
    for i in range(len(strr)):
        summ += ord(strr[i]) - ord("a") + 1
    if summ % 26 == 0:
        return chr(ord("z"))
    else:
        summ = summ % 26
        return chr(ord("a") + summ - 1)

