fn power(a: int, b: int) -> int:
    if b == 0:
        return 1
    elif a == 0:
        return 0
    elif b == 1:
        return a
    else:
        return a * power(a, b - 1)

fn index_minimum(test_list: [(str, int)]) -> str:
    first_name, first_val = test_list[0]
    var best_name = first_name
    var best_val = first_val
    for name, val in test_list:
        if val < best_val:
            best_name = name
            best_val = val
    return best_name

