    flat: [int] = [item for sublist in list1 for item in sublist]
    var dic_data: {int: int} = {}
    for num in flat:
        if num in dic_data:
            dic_data[num] += 1
        else:
            key = num
            value = 1
            dic_data[key] = value
    return dic_data

