fn decimal_to_binary(n: int) -> str:
    if n == 0:
        return "0"
    var m = abs(n)
    var digits: [str] = []
    while m > 0:
        digits.append(str(m % 2))
        m = m // 2
    digits.reverse()
    result = "".join(digits)
    if n < 0:
        return "-" + result
    return result

